"use client";

import type React from "react";
import Link from "next/link";
import { motion } from "motion/react";
import { Sparkles, ArrowRight, ArrowDownRight } from "lucide-react";

import Features from "./featchers";
import Card_01 from "@/components/synapse-ui/cards/card-01";
import Card_25 from "@/components/synapse-ui/cards/card-25";
import { AIInput04 } from "@/components/synapse-ui/ai-inputs/ai-input-04";
import Input_01 from "@/components/synapse-ui/inputs/input-01";
import Input_06 from "@/components/synapse-ui/inputs/input-06";
import Btn01 from "@/components/synapse-ui/buttons/button-01";
import Button02 from "@/components/synapse-ui/buttons/button-02";
import Button08 from "@/components/synapse-ui/buttons/button-08";
import Button09 from "@/components/synapse-ui/buttons/button-09";

// Inline TailwindCSS Logo for portability
const TailwindLogo = () => (
  <svg
    viewBox="0 0 256 154"
    className="w-5 h-5"
    xmlns="http://www.w3.org/2000/svg"
    preserveAspectRatio="xMidYMid"
  >
    <defs>
      <linearGradient x1="-2.778%" y1="32%" x2="100%" y2="67.556%" id="tailwind-logo-grad">
        <stop stopColor="#2298BD" offset="0%" />
        <stop stopColor="#0ED7B5" offset="100%" />
      </linearGradient>
    </defs>
    <path
      d="M128 0C93.867 0 72.533 17.067 64 51.2 76.8 34.133 91.733 27.733 108.8 32c9.737 2.434 16.697 9.499 24.401 17.318C145.751 62.057 160.275 76.8 192 76.8c34.133 0 55.467-17.067 64-51.2-12.8 17.067-27.733 23.467-44.8 19.2-9.737-2.434-16.697-9.499-24.401-17.318C174.249 14.743 159.725 0 128 0ZM64 76.8C29.867 76.8 8.533 93.867 0 128c12.8-17.067 27.733-23.467 44.8-19.2 9.737 2.434 16.697 9.499 24.401 17.318C81.751 138.857 96.275 153.6 128 153.6c34.133 0 55.467-17.067 64-51.2-12.8 17.067-27.733 23.467-44.8 19.2-9.737-2.434-16.697-9.499-24.401-17.318C110.249 91.543 95.725 76.8 64 76.8Z"
      fill="url(#tailwind-logo-grad)"
    />
  </svg>
);

export default function LandingHero() {
  return (
    <div className="mx-auto w-full max-w-7xl min-h-[85vh] flex flex-col lg:flex-row items-center justify-between gap-8 lg:gap-12 px-4 sm:px-6 py-12 md:py-16">
      {/* Left side - Title and CTA */}
      <div className="w-full lg:w-[45%] flex flex-col items-start text-left space-y-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
        >
          <h1 className="text-4xl sm:text-5xl lg:text-6xl font-extrabold tracking-tight leading-[1.1] text-zinc-900 dark:text-zinc-100">
            Craft with{" "}
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-rose-500 via-fuchsia-500 to-purple-500 dark:from-rose-400 dark:via-fuchsia-400 dark:to-purple-400">
              precision
            </span>
            <br />
            build with{" "}
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-purple-500 via-fuchsia-500 to-rose-500 dark:from-purple-400 dark:via-fuchsia-400 dark:to-rose-400">
              ease
            </span>
            .
          </h1>
          <p className="mt-6 text-sm sm:text-base md:text-lg text-zinc-600 dark:text-zinc-400 max-w-lg leading-relaxed">
            A curated collection of{" "}
            <span className="font-semibold text-zinc-800 dark:text-zinc-200">100+ premium UI components</span> crafted with{" "}
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-rose-500 to-fuchsia-500 dark:from-rose-400 dark:to-fuchsia-400 font-bold">
              Tailwind CSS
            </span>{" "}
            and{" "}
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-fuchsia-500 to-purple-500 dark:from-fuchsia-400 dark:to-purple-400 font-bold">
              shadcn/ui
            </span>{" "}
            for modern React and Next.js applications.
          </p>
        </motion.div>

        {/* Action Bar */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="flex flex-col justify-start w-full"
        >
          <span className="text-xs text-zinc-500 dark:text-zinc-400 pb-3 text-start flex items-center gap-2">
            <TailwindLogo />
            <span className="flex items-center gap-1.5 font-medium">
              Now updated for Tailwind CSS 4.0!
              <span className="inline-flex items-center rounded-md bg-purple-50 dark:bg-purple-900/30 px-2 py-0.5 text-[10px] font-semibold text-purple-700 dark:text-purple-300">
                <Sparkles className="h-3 w-3 mr-1" />
                New
              </span>
            </span>
          </span>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-start gap-3 w-full sm:w-auto">
            {/* Browse Components Button */}
            <Link href="/docs" className="group">
              <div className="relative inline-flex w-full sm:w-auto items-center justify-center gap-2 rounded-xl font-semibold h-11 px-5 bg-black text-white dark:bg-white dark:text-black border border-zinc-800 dark:border-zinc-200 hover:opacity-90 active:scale-[0.98] transition-all shadow-xs">
                <span>Browse Components</span>
                <ArrowDownRight className="w-4 h-4 rotate-[270deg] group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
              </div>
            </Link>

            {/* Premium UI Blocks Button */}
            <Link href="#" className="group">
              <div className="relative inline-flex w-full sm:w-auto items-center justify-center gap-2 rounded-xl font-semibold h-11 px-5 bg-white text-black dark:bg-[#0e1111] dark:text-white border border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-900 active:scale-[0.98] transition-all shadow-xs">
                <span>Visit Premium UI Blocks</span>
                <ArrowRight className="w-4 h-4 group-hover:translate-x-0.5 transition-transform" />
              </div>
            </Link>
          </div>
        </motion.div>
        
        <Features />
      </div>

      {/* Right side - Components Layout */}
      <div className="w-full lg:w-[50%] flex flex-col justify-between gap-6 lg:pl-4">
        {/* Top row: Card + Action Search Bar */}
        <motion.div
          initial={{ opacity: 0, y: -20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: 0.5 }}
          className="w-full grid grid-cols-1 sm:grid-cols-2 gap-6 items-center"
        >
          {/* Card component */}
          <div className="w-full flex flex-col items-center justify-center">
            <span className="text-xs text-zinc-400 dark:text-zinc-500 block mb-2 font-mono">card-01</span>
            <div className="w-full max-w-xs">
              <Card_01 href="/docs/components/card" />
            </div>
          </div>

          {/* Action Search Bar */}
          <div className="w-full flex flex-col items-center justify-center">
            <span className="text-xs text-zinc-400 dark:text-zinc-500 block mb-2 font-mono">card-25</span>
            <div className="w-full max-w-xs">
              <Card_25 />
            </div>
          </div>
        </motion.div>

        {/* Middle row: AI Chat Input */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.5, delay: 0.2 }}
          className="w-full flex flex-col items-center"
        >
          <span className="text-xs text-zinc-400 dark:text-zinc-500 block mb-2 font-mono">ai-input-04</span>
          <div className="w-full max-w-md p-4 rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/30 flex items-center justify-center">
            <AIInput04 />
          </div>
        </motion.div>

        {/* Bottom row: Buttons on left, Inputs on right */}
        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: 0.5, delay: 0.4 }}
          className="w-full grid grid-cols-1 sm:grid-cols-2 gap-6"
        >
          {/* Left side - Buttons Stack */}
          <div className="w-full flex flex-col items-center">
            <span className="text-xs text-zinc-400 dark:text-zinc-500 block mb-2 font-mono">buttons showcase</span>
            <div className="w-full max-w-xs flex flex-col items-center gap-3 p-4 rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-zinc-50/30 dark:bg-zinc-900/20">
              <Link href="/docs/components/button">
                <Button02 className="w-40 py-2.5" />
              </Link>
              <Link href="/docs/components/button">
                <Button09 className="w-40 py-2.5" />
              </Link>
              <Link href="/docs/components/button">
                <Btn01 className="w-40 py-2.5" />
              </Link>
              <Link href="/docs/components/button">
                <Button08 className="w-40 py-2.5" />
              </Link>
            </div>
          </div>

          {/* Right side - Inputs Stack */}
          <div className="w-full flex flex-col items-center">
            <span className="text-xs text-zinc-400 dark:text-zinc-500 block mb-2 font-mono">inputs showcase</span>
            <div className="w-full max-w-xs flex flex-col gap-6 p-4 justify-center h-full">
              <Link href="/docs/components/input" className="w-full block">
                <Input_01 />
              </Link>
              <Link href="/docs/components/input" className="w-full block">
                <Input_06 />
              </Link>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";

import {
  Heart,
  MessageCircle,
  Share2,
  Bookmark,
  MoreHorizontal,
  Link as LinkIcon,
} from "lucide-react";

interface Card01Props {
  href: string;
  author?: {
    name?: string;
    username?: string;
    avatar?: string;
    timeAgo?: string;
  };
  content?: {
    text?: string;
    link?: {
      title?: string;
      description?: string;
      icon?: React.ReactNode;
    };
  };
  engagement?: {
    likes?: number;
    comments?: number;
    shares?: number;
    isLiked?: boolean;
    isBookmarked?: boolean;
  };
  onLike?: () => void;
  onComment?: () => void;
  onShare?: () => void;
  onBookmark?: () => void;
}

const defaultProps: Card01Props = {
  href: "",
  author: {
    name: "Dorian Baffier",
    username: "dorian_baffier",
    avatar:
      "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQCYy_Pjw0UWMPSmVN7lL5yhod-0OhxDmeT4g&s",
    timeAgo: "2h ago",
  },
  content: {
    text: "Just launched Synapse UI! Check out the documentation and let me know what you think 🎨",
    link: {
      title: "Synapse UI Documentation",
      description: "A comprehensive guide to Synapse UI",
      icon: <LinkIcon className="w-5 h-5 text-blue-500" />,
    },
  },
  engagement: {
    likes: 128,
    comments: 32,
    shares: 24,
    isLiked: true,
    isBookmarked: false,
  },
};

export default function Card_01({
  href,
  author = defaultProps.author,
  content = defaultProps.content,
  engagement = defaultProps.engagement,
  onLike,
  onComment,
  onShare,
  onBookmark,
}: Card01Props) {
  return (
    <a href={href}>
      <div
        className={cn(
          "w-full max-w-2xl mx-auto",
          "bg-white/50 dark:bg-zinc-900/50 backdrop-blur-xl",
          "border border-zinc-200/50 dark:border-zinc-800/50",
          "rounded-3xl shadow-lg",
          "transition-all duration-300 ease-in-out",
          "hover:shadow-xl hover:shadow-zinc-200/20 dark:hover:shadow-zinc-900/20",
          "hover:border-zinc-300/50 dark:hover:border-zinc-700/50",
          "hover:translate-y-[-2px]",
        )}
      >
        <div className="divide-y divide-zinc-200/50 dark:divide-zinc-800/50">
          <div className="p-7">
            <div className="flex items-center justify-between mb-5">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <img
                    src={author?.avatar}
                    alt={author?.name}
                    className={cn(
                      "w-11 h-11 rounded-full",
                      "ring-2 ring-white dark:ring-zinc-800",
                      "object-cover",
                      "transition-transform duration-300",
                      "group-hover:scale-105",
                    )}
                  />
                  <div className="absolute inset-0 rounded-full bg-linear-to-tr from-rose-500 to-blue-500 opacity-0 hover:opacity-10 transition-opacity duration-300" />
                </div>
                <div>
                  <h3 className="text-[15px] font-semibold text-zinc-900 dark:text-zinc-100 tracking-tight">
                    {author?.name}
                  </h3>
                  <p className="text-[13px] text-zinc-500 dark:text-zinc-400 tracking-tight">
                    @{author?.username} · {author?.timeAgo}
                  </p>
                </div>
              </div>
              <button
                type="button"
                className={cn(
                  "p-2 rounded-full",
                  "transition-all duration-200",
                  "hover:bg-zinc-100/80 dark:hover:bg-zinc-800/80",
                  "active:bg-zinc-200 dark:active:bg-zinc-700",
                  "focus:outline-hidden focus:ring-2 focus:ring-zinc-500/20",
                )}
              >
                <MoreHorizontal className="w-5 h-5 text-zinc-400" />
              </button>
            </div>

            <p className="text-[15px] leading-relaxed text-zinc-600 dark:text-zinc-300 mb-5">
              {content?.text}
            </p>

            {content?.link && (
              <div
                className={cn(
                  "mb-5 rounded-2xl",
                  "border border-zinc-200/80 dark:border-zinc-700/80",
                  "overflow-hidden group cursor-pointer",
                  "transition-all duration-300",
                  "hover:border-zinc-300 dark:hover:border-zinc-600",
                  "hover:shadow-md hover:shadow-zinc-200/20 dark:hover:shadow-zinc-900/20",
                  "hover:translate-y-[-1px]",
                )}
              >
                <div
                  className={cn(
                    "p-5",
                    "bg-linear-to-b from-zinc-50/50 to-white dark:from-zinc-800/30 dark:to-zinc-800/50",
                    "group-hover:from-zinc-100/50 group-hover:to-zinc-50/50",
                    "dark:group-hover:from-zinc-800/50 dark:group-hover:to-zinc-800/70",
                    "transition-colors duration-300",
                  )}
                >
                  <div className="flex items-center gap-4">
                    <div className="p-2.5 bg-white/80 dark:bg-zinc-700/80 rounded-xl shadow-xs backdrop-blur-xs">
                      {content?.link.icon}
                    </div>
                    <div>
                      <h4 className="text-[14px] font-medium text-zinc-900 dark:text-zinc-100 mb-0.5">
                        {content?.link.title}
                      </h4>
                      <p className="text-[13px] text-zinc-500 dark:text-zinc-400">
                        {content?.link.description}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            <div className="flex items-center justify-between pt-2">
              <div className="flex items-center gap-6">
                <button
                  type="button"
                  onClick={onLike}
                  className={cn(
                    "flex items-center gap-2.5 text-[13px] font-medium p-2.5 rounded-full",
                    "transition-all duration-300",
                    "hover:bg-rose-50/80 dark:hover:bg-rose-950/30",
                    "active:bg-rose-100 dark:active:bg-rose-950/50",
                    "focus:outline-hidden focus:ring-2 focus:ring-rose-500/20",
                    engagement?.isLiked
                      ? "text-rose-600"
                      : "text-zinc-500 dark:text-zinc-400 hover:text-rose-600",
                  )}
                >
                  <Heart
                    className={cn(
                      "w-[18px] h-[18px]",
                      "transition-all duration-300",
                      "hover:scale-110",
                      "active:scale-95",
                      engagement?.isLiked && "fill-current",
                    )}
                  />
                  <span>{engagement?.likes}</span>
                </button>
                <button
                  type="button"
                  onClick={onComment}
                  className={cn(
                    "flex items-center gap-2.5 text-[13px] font-medium p-2.5 rounded-full",
                    "transition-all duration-300",
                    "hover:bg-blue-50/80 dark:hover:bg-blue-950/30",
                    "active:bg-blue-100 dark:active:bg-blue-950/50",
                    "focus:outline-hidden focus:ring-2 focus:ring-blue-500/20",
                    "text-zinc-500 dark:text-zinc-400 hover:text-blue-500",
                  )}
                >
                  <MessageCircle className="w-[18px] h-[18px] transition-transform duration-300 hover:scale-110" />
                  <span>{engagement?.comments}</span>
                </button>
                <button
                  type="button"
                  onClick={onShare}
                  className={cn(
                    "flex items-center gap-2.5 text-[13px] font-medium p-2.5 rounded-full",
                    "transition-all duration-300",
                    "hover:bg-green-50/80 dark:hover:bg-green-950/30",
                    "active:bg-green-100 dark:active:bg-green-950/50",
                    "focus:outline-hidden focus:ring-2 focus:ring-green-500/20",
                    "text-zinc-500 dark:text-zinc-400 hover:text-green-500",
                  )}
                >
                  <Share2 className="w-[18px] h-[18px] transition-transform duration-300 hover:scale-110" />
                  <span>{engagement?.shares}</span>
                </button>
              </div>
              <button
                type="button"
                onClick={onBookmark}
                className={cn(
                  "p-2.5 rounded-full",
                  "transition-all duration-300",
                  "hover:bg-zinc-100/80 dark:hover:bg-zinc-800/80",
                  "active:bg-zinc-200 dark:active:bg-zinc-700",
                  "focus:outline-hidden focus:ring-2 focus:ring-zinc-500/20",
                  engagement?.isBookmarked ? "text-zinc-900 dark:text-zinc-100" : "text-zinc-400",
                )}
              >
                <Bookmark
                  className={cn(
                    "w-[18px] h-[18px]",
                    "transition-all duration-300",
                    "hover:scale-110",
                    "active:scale-95",
                    engagement?.isBookmarked && "fill-current",
                  )}
                />
              </button>
            </div>
          </div>
        </div>
      </div>
    </a>
  );
}

"use client";
import { Calendar, Sparkles, Code2, ExternalLink, Share2 } from "lucide-react";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface Skill {
  name: string;
  level: number;
}

interface Card02Props {
  name?: string;
  role?: string;
  image?: string;
  status?: string;
  skills?: Skill[];
  portfolio?: string;
}

const defaultProfile = {
  name: "Eugene K",
  role: "Senior Developer",
  image:
    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQCYy_Pjw0UWMPSmVN7lL5yhod-0OhxDmeT4g&s",
  status: "Open to Work",
  skills: [
    { name: "Frontend", level: 5 },
    { name: "Backend", level: 4 },
    { name: "DevOps", level: 4 },
  ],
  portfolio: "github.com/alexchen",
} satisfies Required<Card02Props>;

export default function Card_25({
  name = defaultProfile.name,
  role = defaultProfile.role,
  image = defaultProfile.image,
  status = defaultProfile.status,
  skills = defaultProfile.skills,
  portfolio = defaultProfile.portfolio,
}: Card02Props = defaultProfile) {
  return (
    <div className="w-full max-w-xs mx-auto">
      <div
        className={cn(
          "relative overflow-hidden",
          "bg-white/50 dark:bg-zinc-900/50",
          "backdrop-blur-xl",
          "border border-zinc-200/50 dark:border-zinc-800/50",
          "rounded-2xl",
          "transition-all duration-300",
          "hover:shadow-xl hover:shadow-zinc-200/20 dark:hover:shadow-zinc-900/20",
          "hover:border-zinc-300/50 dark:hover:border-zinc-700/50",
        )}
      >
        <div className="p-5">
          <div className="flex items-center gap-4">
            <div className="relative group">
              <div
                className={cn(
                  "w-16 h-16 rounded-xl overflow-hidden",
                  "ring-2 ring-zinc-100 dark:ring-zinc-800",
                )}
              >
                <Image src={image} alt={name} width={64} height={64} className="object-cover" />
              </div>
            </div>

            <div className="flex-1">
              <h3 className="text-base font-semibold text-zinc-900 dark:text-zinc-100">{name}</h3>
              <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-0.5">{role}</p>
              <div
                className={cn(
                  "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg",
                  "bg-emerald-50 dark:bg-emerald-900/20",
                  "text-emerald-600 dark:text-emerald-400",
                  "text-xs font-medium",
                )}
              >
                <Calendar className="w-3 h-3" />
                {status}
              </div>
            </div>
          </div>
        </div>

        <div className="px-5 pb-5">
          <div className="space-y-2.5">
            {skills?.map((skill) => (
              <div
                key={skill.name}
                className={cn(
                  "flex items-center gap-3",
                  "p-2 rounded-xl",
                  "bg-zinc-50 dark:bg-zinc-800/50",
                  "hover:bg-zinc-100 dark:hover:bg-zinc-800",
                  "transition-colors duration-200",
                )}
              >
                <Code2 className="w-4 h-4 text-zinc-900 dark:text-zinc-100" />
                <div className="flex-1">
                  <div className="flex items-center justify-between text-sm mb-1.5">
                    <span className="text-zinc-700 dark:text-zinc-300 font-medium">
                      {skill.name}
                    </span>
                  </div>
                  <div className="flex gap-1">
                    {[...Array(5)].map((_, i) => (
                      <div
                        key={i}
                        className={cn(
                          "h-1 rounded-full flex-1",
                          i < skill.level
                            ? "bg-zinc-900 dark:bg-zinc-100"
                            : "bg-zinc-200 dark:bg-zinc-700",
                        )}
                      />
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="px-5 pb-5 flex gap-2 items-center">
          <Button
            variant="default"
            size="sm"
            className={cn(
              "w-full",
              "bg-zinc-900 dark:bg-zinc-100",
              "hover:bg-zinc-700 dark:hover:bg-zinc-300",
              "text-white dark:text-zinc-900",
              "shadow-xs",
            )}
          >
            <ExternalLink className="w-4 h-4 mr-2" />
            View Portfolio
          </Button>
          <Button
            variant="ghost"
            className="flex items-center gap-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg p-1.5"
          >
            <Share2 className="w-4 h-4 text-zinc-900 dark:text-zinc-100" />
            <span className="text-sm text-zinc-900 dark:text-zinc-100">Share</span>
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ArrowUp, FileText, Code, Image as ImageIcon, Brain, Wand2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { useAutoResizeTextarea } from "@/hooks/use-auto-resize-textarea";

const QUICK_ACTIONS = [
  { id: "write", icon: FileText, label: "Write", color: "text-blue-500" },
  { id: "code", icon: Code, label: "Code", color: "text-emerald-500" },
  { id: "image", icon: ImageIcon, label: "Image", color: "text-violet-500" },
  { id: "analyze", icon: Brain, label: "Analyze", color: "text-amber-500" },
  { id: "improve", icon: Wand2, label: "Improve", color: "text-rose-500" },
] as const;

interface AIInput04Props {
  value?: string;
  onChange?: (value: string) => void;
  onSubmit?: (value: string) => void;
  onActionClick?: (action: string) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

export function AIInput04({
  value: controlledValue,
  onChange,
  onSubmit,
  onActionClick,
  placeholder = "What would you like to create?",
  disabled = false,
  className,
}: AIInput04Props) {
  const [internalValue, setInternalValue] = React.useState("");
  const [activeAction, setActiveAction] = React.useState<string | null>(null);
  const value = controlledValue ?? internalValue;
  const setValue = onChange ?? setInternalValue;

  const { textareaRef, adjustHeight } = useAutoResizeTextarea({
    minHeight: 56,
    maxHeight: 200,
  });

  const handleSubmit = () => {
    if (!value.trim() || disabled) return;
    onSubmit?.(value);
    setValue("");
    setActiveAction(null);
    adjustHeight(true);
  };

  const handleActionClick = (id: string, label: string) => {
    setActiveAction(id);
    onActionClick?.(id);
  };

  const currentAction = QUICK_ACTIONS.find((a) => a.id === activeAction);

  return (
    <div className={cn("w-full max-w-xl mx-auto", className)}>
      {/* Action chips */}
      <div className="flex flex-wrap gap-2 mb-3">
        {QUICK_ACTIONS.map((action) => (
          <button
            key={action.id}
            type="button"
            disabled={disabled}
            onClick={() => handleActionClick(action.id, action.label)}
            className={cn(
              "flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[13px] font-medium",
              "border transition-all duration-200",
              activeAction === action.id
                ? [
                    "border-transparent",
                    "bg-zinc-900 dark:bg-zinc-100",
                    "text-white dark:text-zinc-900",
                    "shadow-sm",
                  ]
                : [
                    "border-zinc-200 dark:border-zinc-800",
                    "bg-white dark:bg-zinc-950",
                    "text-zinc-600 dark:text-zinc-400",
                    "hover:border-zinc-300 dark:hover:border-zinc-700",
                    "hover:bg-zinc-50 dark:hover:bg-zinc-900",
                  ],
            )}
          >
            <action.icon
              className={cn(
                "size-3.5 transition-colors",
                activeAction === action.id ? "text-current" : action.color,
              )}
            />
            {action.label}
          </button>
        ))}
      </div>

      {/* Input */}
      <div
        className={cn(
          "relative rounded-2xl border bg-white dark:bg-zinc-950",
          "border-zinc-200 dark:border-zinc-800",
          "shadow-[0_2px_16px_-4px_rgba(0,0,0,0.08)] dark:shadow-[0_2px_16px_-4px_rgba(0,0,0,0.4)]",
          "focus-within:border-zinc-300 dark:focus-within:border-zinc-700",
          "focus-within:shadow-[0_4px_24px_-4px_rgba(0,0,0,0.12)] dark:focus-within:shadow-[0_4px_24px_-4px_rgba(0,0,0,0.5)]",
          "transition-all duration-300",
          disabled && "opacity-50",
        )}
      >
        {/* Active action indicator */}
        {currentAction && (
          <div className="flex items-center gap-2 px-4 pt-3 pb-0">
            <div
              className={cn("flex items-center gap-1.5 text-xs font-medium", currentAction.color)}
            >
              <currentAction.icon className="size-3" />
              {currentAction.label} mode
            </div>
            <button
              type="button"
              onClick={() => setActiveAction(null)}
              className="text-[10px] text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300 ml-auto"
            >
              ✕ clear
            </button>
          </div>
        )}

        <textarea
          ref={textareaRef}
          placeholder={currentAction ? `${currentAction.label} something...` : placeholder}
          disabled={disabled}
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            adjustHeight();
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              handleSubmit();
            }
          }}
          rows={1}
          className={cn(
            "w-full resize-none bg-transparent",
            "py-4 pl-4 pr-14",
            "text-[15px] text-zinc-800 dark:text-zinc-100",
            "placeholder:text-zinc-400 dark:placeholder:text-zinc-600",
            "outline-none border-none ring-0",
            "min-h-[56px] max-h-[200px]",
            "leading-relaxed",
            currentAction && "pt-2",
          )}
        />

        <button
          type="button"
          disabled={!value.trim() || disabled}
          onClick={handleSubmit}
          className={cn(
            "absolute right-2.5 bottom-2.5",
            "flex items-center justify-center size-9 rounded-xl",
            "transition-all duration-200",
            value.trim()
              ? "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:opacity-90 active:scale-95 shadow-sm"
              : "bg-zinc-100 dark:bg-zinc-800 text-zinc-300 dark:text-zinc-600 cursor-not-allowed",
          )}
        >
          <ArrowUp className="size-4" />
        </button>
      </div>
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import { cn } from "@/lib/utils";
import { X, Check } from "lucide-react";

interface SimpleInputProps {
  label?: string;
  placeholder?: string;
  error?: string;
  success?: string;
  onChange?: (value: string) => void;
  onClear?: () => void;
  type?: "text" | "email" | "password" | "search";
}

export default function Input_01({
  label = "Label",
  placeholder = "Type something...",
  error,
  success,
  onChange,
  onClear,
  type = "text",
}: SimpleInputProps) {
  const [value, setValue] = useState("");
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleClear = () => {
    setValue("");
    onClear?.();
    inputRef.current?.focus();
  };

  return (
    <div className="w-full max-w-xs space-y-1.5">
      <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300" htmlFor={label}>
        {label}
      </label>

      <div className="relative group">
        <input
          ref={inputRef}
          type={type}
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            onChange?.(e.target.value);
          }}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder={placeholder}
          className={cn(
            "w-full px-3 py-2",
            "rounded-lg",
            "bg-white dark:bg-zinc-900",
            "border border-zinc-200 dark:border-zinc-800",
            "text-sm text-zinc-900 dark:text-zinc-100",
            "placeholder:text-zinc-400 dark:placeholder:text-zinc-600",
            "transition-all duration-200",
            "focus:outline-hidden focus:ring-2",
            error
              ? "border-red-500 focus:ring-red-500/20"
              : success
                ? "border-green-500 focus:ring-green-500/20"
                : "focus:ring-indigo-500/20",
            isFocused && "border-indigo-500",
          )}
        />

        {/* Clear button */}
        {value && (
          <button
            onClick={handleClear}
            className={cn(
              "absolute right-2 top-1/2 -translate-y-1/2",
              "p-1 rounded-md",
              "text-zinc-400 hover:text-zinc-600",
              "dark:text-zinc-600 dark:hover:text-zinc-400",
              "transition-colors",
            )}
          >
            <X className="w-4 h-4" />
          </button>
        )}

        {/* Status indicator */}
        <div
          className={cn(
            "absolute -right-4 top-1/2 -translate-y-1/2",
            "transition-opacity duration-200",
            !error && !success && "opacity-0",
          )}
        >
          {error ? (
            <X className="w-4 h-4 text-red-500" />
          ) : success ? (
            <Check className="w-4 h-4 text-green-500" />
          ) : null}
        </div>
      </div>

      {/* Error/Success message */}
      {(error || success) && (
        <p className={cn("text-sm", error ? "text-red-500" : "text-green-500")}>
          {error || success}
        </p>
      )}
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { cn } from "@/lib/utils";

const OTP_LENGTH = 6;

export default function Input_06() {
  const [code, setCode] = useState<string[]>(Array(OTP_LENGTH).fill(""));
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
  const [shake, setShake] = useState(false);

  useEffect(() => {
    inputRefs.current = inputRefs.current.slice(0, OTP_LENGTH);
  }, []);

  const handleChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newCode = [...code];
    newCode[index] = value.slice(-1);
    setCode(newCode);

    if (value && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
      setActiveIndex(index + 1);
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace" && !code[index] && index > 0) {
      // Move to previous input on backspace if current input is empty
      inputRefs.current[index - 1]?.focus();
      setActiveIndex(index - 1);
    } else if (e.key === "ArrowLeft" && index > 0) {
      inputRefs.current[index - 1]?.focus();
      setActiveIndex(index - 1);
    } else if (e.key === "ArrowRight" && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
      setActiveIndex(index + 1);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData("text/plain").slice(0, OTP_LENGTH);

    if (!/^\d+$/.test(pastedData)) {
      setShake(true);
      setTimeout(() => setShake(false), 600);
      return;
    }

    const newCode = [...code];
    pastedData.split("").forEach((digit, index) => {
      newCode[index] = digit;
    });
    setCode(newCode);

    const focusIndex = Math.min(pastedData.length, OTP_LENGTH - 1);
    inputRefs.current[focusIndex]?.focus();
    setActiveIndex(focusIndex);
  };

  const setInputRef = useCallback(
    (index: number) => (el: HTMLInputElement | null) => {
      inputRefs.current[index] = el;
    },
    [],
  );

  return (
    <div className="w-full max-w-sm space-y-2">
      <fieldset className={cn("flex flex-col gap-2", shake && "animate-shake")}>
        <legend className="text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-2">
          Verification Code
        </legend>

        <div className="flex gap-2 items-center justify-start">
          {Array.from({ length: OTP_LENGTH }).map((_, index) => (
            <div key={`otp-input-${index}`} className="relative">
              <input
                id={`otp-input-${index}`}
                ref={setInputRef(index)}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={code[index]}
                onChange={(e) => handleChange(index, e.target.value)}
                onKeyDown={(e) => handleKeyDown(index, e)}
                onPaste={handlePaste}
                onFocus={() => setActiveIndex(index)}
                className={cn(
                  "w-12 h-14 text-center text-lg font-semibold",
                  "rounded-lg border",
                  "transition-all duration-200",
                  "bg-white dark:bg-zinc-900",
                  "border-zinc-200 dark:border-zinc-800",
                  activeIndex === index && "border-indigo-500 dark:border-indigo-500",
                  "focus:outline-hidden focus:ring-2",
                  "focus:ring-indigo-500/20",
                )}
                suppressHydrationWarning
              />
              {index !== 6 - 1 && (
                <div className="absolute top-1/2 -right-2 w-2 transform -translate-y-1/2">
                  <div className="w-1 h-1 rounded-full bg-zinc-300 dark:bg-zinc-600" />
                </div>
              )}
            </div>
          ))}
        </div>
      </fieldset>
    </div>
  );
}

